void FControlRigPoseAdapter::ConvertToLocalPose()
{
	DECLARE_SCOPE_HIERARCHICAL_COUNTER_FUNC()

	check(ParentPoseIndices.Num() == GlobalPose.Num());
	LocalPose.SetNum(GlobalPose.Num());

	if (URigHierarchy* Hierarchy = GetHierarchy())
	{
		for (int32 Index = 0; Index < ParentPoseIndices.Num(); Index++)
		{
			(void)GetLocalTransform(Index);
		}
	}

}

const FTransform& FControlRigPoseAdapter::GetLocalTransform(int32 InIndex)
{
	DECLARE_SCOPE_HIERARCHICAL_COUNTER_FUNC()

	check(LocalPose.IsValidIndex(InIndex));
	check(LocalPoseIsDirty.IsValidIndex(InIndex));
	check(ParentPoseIndices.IsValidIndex(InIndex));
	check(RequiresHierarchyForSpaceConversion.IsValidIndex(InIndex));

	URigHierarchy* Hierarchy = GetHierarchy();
	check(Hierarchy);

	if (LocalPoseIsDirty[InIndex])
	{
		check(GlobalPoseIsDirty[InIndex] == false);
		if (RequiresHierarchyForSpaceConversion[InIndex] && PoseIndexToElementIndex.IsValidIndex(InIndex))
		{
			LocalPose[InIndex] = Hierarchy->GetLocalTransformByIndex(PoseIndexToElementIndex[InIndex]);
		}
		else
		{
			const FCompactPoseBoneIndex ParentIndex = ParentPoseIndices[InIndex];
			if (!ParentIndex.IsValid())
			{
				LocalPose[InIndex] = GetGlobalTransform(InIndex);
			}
			else
			{
				LocalPose[InIndex] = GetGlobalTransform(InIndex).GetRelativeTransform(GetGlobalTransform(ParentIndex.GetInt()));
			}
			LocalPose[InIndex].NormalizeRotation();
		}
		LocalPoseIsDirty[InIndex] = false;
	}
	return LocalPose[InIndex];
}

void FControlRigHierarchyMappings::UpdateOutput(UControlRig* ControlRig
	, FPoseContext& InOutput
	, const FControlRigIOSettings& InOutputSettings
	, TWeakObjectPtr<UNodeMappingContainer>& InNodeMappingContainer
	, bool bInExecute
	, bool bInTransferPoseInGlobalSpace)
{
	DECLARE_SCOPE_HIERARCHICAL_COUNTER_FUNC()

	URigHierarchy* Hierarchy = ControlRig->GetHierarchy();
	if (!IsValid(Hierarchy))
	{
		return;
	}

	if (bEnablePoseAdapter)
	{
		if (InOutputSettings.bUpdatePose)
		{
			if (PoseAdapter)
			{
				// make sure the local respectively global transforms are all ready
				if (PoseAdapter->GetTransferInLocalSpace())
				{
					PoseAdapter->ConvertToLocalPose();
				}
				else
				{
					PoseAdapter->ConvertToGlobalPose();
				}

				// if we transfered in global - let's convert back to local
				if (!PoseAdapter->GetTransferInLocalSpace())
				{
					if (PoseAdapter->GetGlobalPose().Num() == InOutput.Pose.GetNumBones())
					{
						PoseAdapter->ConvertToLocalPose();
					}
				}

				InOutput.Pose.CopyBonesFrom(PoseAdapter->GetLocalPose());
			}
		}

	else
	{
		ParentTransform = GetParentTransform(InTransformElement, GlobalType);

		FTransform NewTransform = InTransformElement->GetTransform().Get(OpposedType).GetRelativeTransform(ParentTransform);
		NewTransform.NormalizeRotation();
		CompensateZeroScale(NewTransform);
		InTransformElement->GetTransform().Set(InTransformType, NewTransform);
		InTransformElement->GetDirtyState().MarkClean(InTransformType);
	}
}

TTransform<T> TTransform<T>::GetRelativeTransform(const TTransform<T>& Other) const
{
	// A * B(-1) = VQS(B)(-1) (VQS (A))
	// 
	// Scale = S(A)/S(B)
	// Rotation = Q(B)(-1) * Q(A)
	// Translation = 1/S(B) *[Q(B)(-1)*(T(A)-T(B))*Q(B)]
	// where A = this, B = Other
	TTransform<T> Result;

	if (Other.IsRotationNormalized() == false)
	{
		return TTransform<T>::Identity;
	}

	if (Private_AnyHasNegativeScale(this->Scale3D, Other.Scale3D))
	{
		// @note, if you have 0 scale with negative, you're going to lose rotation as it can't convert back to quat
		GetRelativeTransformUsingMatrixWithScale(&Result, this, &Other);
	}
	else
	{
		// Scale = S(A)/S(B)
		static ScalarRegister STolerance(UE_SMALL_NUMBER);
		TransformVectorRegister VSafeScale3D = VectorSet_W0(GetSafeScaleReciprocal(Other.Scale3D, STolerance));

		TransformVectorRegister VScale3D = VectorMultiply(Scale3D, VSafeScale3D);

		//VQTranslation = (  ( T(A).X - T(B).X ),  ( T(A).Y - T(B).Y ), ( T(A).Z - T(B).Z), 0.f );
		TransformVectorRegister VQTranslation = VectorSet_W0(VectorSubtract(Translation, Other.Translation));

		// Inverse RotatedTranslation
		TransformVectorRegister VInverseRot = VectorQuaternionInverse(Other.Rotation);
		TransformVectorRegister VR = VectorQuaternionRotateVector(VInverseRot, VQTranslation);

		//Translation = 1/S(B)
		TransformVectorRegister VTranslation = VectorMultiply(VR, VSafeScale3D);

		// Rotation = Q(B)(-1) * Q(A)	
		TransformVectorRegister VRotation = VectorQuaternionMultiply2(VInverseRot, Rotation);

		Result.Scale3D = VScale3D;
		Result.Translation = VTranslation;
		Result.Rotation = VRotation;

		Result.DiagnosticCheckNaN_All();
#if DEBUG_INVERSE_TRANSFORM
		TMatrix<T> AM = ToMatrixWithScale();
		TMatrix<T> BM = Other.ToMatrixWithScale();

		Result.DebugEqualMatrix(AM *  BM.InverseFast());
#endif
	}

	return Result;
}

FORCEINLINE VectorRegister4Double VectorQuaternionRotateVector(VectorRegister4Double Quat, VectorRegister4Double VectorW0)
{
	const VectorRegister4Double QW = VectorReplicate(Quat, 3);
	VectorRegister4Double T = VectorCross(Quat, VectorW0);
	T = VectorAdd(T, T);
	const VectorRegister4Double VTemp0 = VectorMultiplyAdd(QW, T, VectorW0);
	const VectorRegister4Double VTemp1 = VectorCross(Quat, T);
	const VectorRegister4Double Rotated = VectorAdd(VTemp0, VTemp1);
	return Rotated;
}

/**
 * Rotate a vector using the inverse of a unit Quaternion (rotation in the opposite direction).
 *
 * @param Quat Unit Quaternion to use for rotation.

FORCEINLINE VectorRegister4Double VectorMultiplyAdd(VectorRegister4Double Vec1, VectorRegister4Double Vec2, VectorRegister4Double Acc)
{
	VectorRegister4Double Result;
	Result.XY = vfmaq_f64(Acc.XY, Vec1.XY, Vec2.XY);
	Result.ZW = vfmaq_f64(Acc.ZW, Vec1.ZW, Vec2.ZW);
	return Result;
}

/**
 * Multiplies two vectors (component-wise) and subtracts the result from the third vector.
 *
 * @param Vec1	1st vector
 * @param Vec2	2nd vector
 * @param Sub	3rd vector
 * @return		VectorRegister4Float( Sub.x - Vec1.x*Vec2.x, Sub.y - Vec1.y*Vec2.y, Sub.z - Vec1.z*Vec2.z, Sub.w - Vec1.w*Vec2.w )
 */
FORCEINLINE VectorRegister4Float VectorNegateMultiplyAdd(VectorRegister4Float Vec1, VectorRegister4Float Vec2, VectorRegister4Float Sub)
{
	return vfmsq_f32(Sub, Vec1, Vec2);
}

FORCEINLINE VectorRegister4Double VectorNegateMultiplyAdd(VectorRegister4Double Vec1, VectorRegister4Double Vec2, VectorRegister4Double Sub)
{
	VectorRegister4Double Result;
	Result.XY = vfmsq_f64(Sub.XY, Vec1.XY, Vec2.XY);
	Result.ZW = vfmsq_f64(Sub.ZW, Vec1.ZW, Vec2.ZW);
	return Result;
}

FORCEINLINE VectorRegister4Double VectorCross(VectorRegister4Double Vec1, VectorRegister4Double Vec2)
{
	VectorRegister4Double C = VectorMultiply(Vec1, VectorSwizzle(Vec2, 1, 2, 0, 3));
	C = VectorNegateMultiplyAdd(VectorSwizzle(Vec1, 1, 2, 0, 3), Vec2, C);
	C = VectorSwizzle(C, 1, 2, 0, 3);
	return C;
}

[[nodiscard]] static inline TransformVectorRegister	GetSafeScaleReciprocal(TransformVectorRegister InScale, const ScalarRegister& Tolerance = ScalarRegister(GlobalVectorConstants::SmallNumber))
{		
	// SafeReciprocalScale.X = (InScale.X == 0) ? 0.f : 1/InScale.X; // same for YZW

	/// TransformVectorRegister( 1.0f / InScale.x, 1.0f / InScale.y, 1.0f / InScale.z, 1.0f / InScale.w )
	const TransformVectorRegister ReciprocalScale = VectorReciprocalAccurate(InScale);

	//TransformVectorRegister( Vec1.x == Vec2.x ? 0xFFFFFFFF : 0, same for yzw )
	const TransformVectorRegister ScaleZeroMask = VectorCompareGE(TransformVectorRegister(Tolerance.Value), VectorAbs(InScale));

	//const TransformVectorRegister ScaleZeroMask = VectorCompareEQ(InScale, VectorZero());

	// TransformVectorRegister( for each bit i: Mask[i] ? Vec1[i] : Vec2[i] )
	const TransformVectorRegister SafeReciprocalScale = VectorSelect(ScaleZeroMask, VectorZero(), ReciprocalScale);

	return SafeReciprocalScale;
}

